/* DAL TRAINING offline support. Generated by scripts/build-sw.js – do not edit www/sw.js. */
const CACHE = 'dal-training-__VERSION__';
const FILES = __FILES__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      // Add files one by one so one failure does not block the whole install.
      await Promise.all(FILES.map((f) => cache.add(new Request(f, { cache: 'reload' })).catch(() => {})));
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('dal-training-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;

  // Audio/video use range requests: serve from cache when possible, else network.
  if (req.headers.has('range')) {
    event.respondWith(
      caches.match(req.url, { ignoreSearch: true }).then(async (hit) => {
        if (!hit) return fetch(req);
        const buf = await hit.arrayBuffer();
        const m = /bytes=(\d+)-(\d+)?/.exec(req.headers.get('range'));
        const start = +m[1];
        const end = m[2] ? +m[2] : buf.byteLength - 1;
        return new Response(buf.slice(start, end + 1), {
          status: 206,
          headers: {
            'Content-Type': hit.headers.get('Content-Type') || 'application/octet-stream',
            'Content-Range': `bytes ${start}-${end}/${buf.byteLength}`,
            'Content-Length': String(end - start + 1),
            'Accept-Ranges': 'bytes'
          }
        });
      })
    );
    return;
  }

  // Pages: app shell. Everything else: cache first, then network (and store it).
  if (req.mode === 'navigate') {
    event.respondWith(caches.match('./').then((hit) => hit || fetch(req)));
    return;
  }
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) =>
      hit || fetch(req).then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
        return res;
      })
    )
  );
});
